#!/usr/bin/env python3
"""
Container Gate DRO Appointment Planning — PySCIPOpt Solver
"""

import csv
import json
import os
import sys
from collections import defaultdict

from pyscipopt import Model, quicksum, SCIP

# ---------------------------------------------------------------------------
# Data loading
# ---------------------------------------------------------------------------

DATA_DIR = "/app/data"
OUT_DIR = "/app/submissions"


def load_data():
    cfg = {}
    with open(os.path.join(DATA_DIR, "config.json")) as f:
        cfg = json.load(f)

    slots = []
    with open(os.path.join(DATA_DIR, "time_slots.csv")) as f:
        for row in csv.DictReader(f):
            slots.append(row)
    slots.sort(key=lambda r: int(r["slot_index"]))

    classes = []
    with open(os.path.join(DATA_DIR, "truck_classes.csv")) as f:
        for row in csv.DictReader(f):
            classes.append(row)

    blocks = []
    with open(os.path.join(DATA_DIR, "yard_blocks.csv")) as f:
        for row in csv.DictReader(f):
            blocks.append(row)

    eligibility = []
    with open(os.path.join(DATA_DIR, "class_block_eligibility.csv")) as f:
        for row in csv.DictReader(f):
            eligibility.append(row)

    scenarios = []
    with open(os.path.join(DATA_DIR, "scenarios.csv")) as f:
        for row in csv.DictReader(f):
            scenarios.append(row)

    demand = {}
    with open(os.path.join(DATA_DIR, "scenario_demand.csv")) as f:
        for row in csv.DictReader(f):
            key = (row["scenario_id"], row["slot_id"], row["class_id"])
            demand[key] = int(row["requested_trucks"])

    block_cap = {}
    with open(os.path.join(DATA_DIR, "scenario_block_capacity.csv")) as f:
        for row in csv.DictReader(f):
            key = (row["scenario_id"], row["slot_id"], row["block_id"])
            block_cap[key] = float(row["capacity_multiplier"])

    mix_limits = []
    with open(os.path.join(DATA_DIR, "slot_class_mix_limits.csv")) as f:
        for row in csv.DictReader(f):
            mix_limits.append(row)

    pool_limits = []
    with open(os.path.join(DATA_DIR, "team_pool_limits.csv")) as f:
        for row in csv.DictReader(f):
            pool_limits.append(row)

    commitments = []
    with open(os.path.join(DATA_DIR, "scenario_service_commitments.csv")) as f:
        for row in csv.DictReader(f):
            commitments.append(row)

    return cfg, slots, classes, blocks, eligibility, scenarios, demand, block_cap, mix_limits, pool_limits, commitments


# ---------------------------------------------------------------------------
# Build model
# ---------------------------------------------------------------------------

def solve():
    cfg, slots, classes, blocks, eligibility, scenarios, demand, block_cap, mix_limits, pool_limits, commitments = load_data()

    slot_ids = [s["slot_id"] for s in slots]
    class_ids = [c["class_id"] for c in classes]
    block_ids = [b["block_id"] for b in blocks]
    scen_ids = [s["scenario_id"] for s in scenarios]

    slot_index = {s["slot_id"]: i for i, s in enumerate(slots)}
    class_index = {c["class_id"]: i for i, c in enumerate(classes)}
    block_index = {b["block_id"]: i for i, b in enumerate(blocks)}
    scen_index = {s["scenario_id"]: i for i, s in enumerate(scenarios)}

    # Lookup dicts
    slot_data = {s["slot_id"]: s for s in slots}
    class_data = {c["class_id"]: c for c in classes}
    block_data = {b["block_id"]: b for b in blocks}
    scen_data = {s["scenario_id"]: s for s in scenarios}

    # Eligibility: (class, block) -> (work_units, handling_cost)
    elig = {}
    for e in eligibility:
        key = (e["class_id"], e["block_id"])
        elig[key] = (float(e["work_units"]), float(e["handling_cost"]))

    # Allowed slots per class
    allowed_slots = {}
    for c in classes:
        allowed_slots[c["class_id"]] = set(c["allowed_slots"].split("|"))

    # Latest service slot index
    latest_service = {}
    for c in classes:
        latest_service[c["class_id"]] = slot_index[c["latest_service_slot"]]

    # Cutoff zero queue
    cutoff_zero = {}
    for c in classes:
        cutoff_zero[c["class_id"]] = int(c["cutoff_zero_queue"])

    # Reefer flag
    reefer_flag = {}
    for c in classes:
        reefer_flag[c["class_id"]] = int(c["reefer_flag"])

    # Exposure units
    exposure_units = {}
    for c in classes:
        exposure_units[c["class_id"]] = float(c["exposure_units"])

    # Shortage penalty
    shortage_penalty = {}
    for c in classes:
        shortage_penalty[c["class_id"]] = float(c["shortage_penalty"])

    # Waiting cost
    waiting_cost = {}
    for c in classes:
        waiting_cost[c["class_id"]] = float(c["waiting_cost_per_slot"])

    # Block base work units
    block_base_work = {}
    for b in blocks:
        block_base_work[b["block_id"]] = float(b["base_work_units"])

    # Block max extra teams
    block_max_teams = {}
    for b in blocks:
        block_max_teams[b["block_id"]] = int(b["max_extra_teams"])

    # Scenario probability and gate multiplier
    scen_prob = {}
    scen_gate_mult = {}
    for s in scenarios:
        scen_prob[s["scenario_id"]] = float(s["probability"])
        scen_gate_mult[s["scenario_id"]] = float(s["gate_multiplier"])

    # Config values
    quota_admin_cost = float(cfg["quota_admin_cost"])
    extra_team_cost = float(cfg["extra_team_cost"])
    max_extra_teams_per_slot = int(cfg["max_extra_teams_per_slot"])
    min_total_quota = int(cfg["minimum_total_quota"])
    max_total_quota = int(cfg["maximum_total_quota"])
    quota_ramp_limit = int(cfg["quota_ramp_limit"])
    tail_risk_alpha = float(cfg["tail_risk_alpha"])
    tail_risk_weight = float(cfg["tail_risk_weight"])
    team_work_unit_gain = float(cfg["team_work_unit_gain"])

    # Build model
    model = Model("container_gate_dro")
    model.setParam("gaprel", 0.0005)

    # Time limit
    time_limit = 300.0
    if "ORCLAW_SOLVE_TIME_LIMIT_SECONDS" in os.environ:
        time_limit = min(time_limit, float(os.environ["ORCLAW_SOLVE_TIME_LIMIT_SECONDS"]))
    model.setParam("limits/time", time_limit)

    # Variables
    # q[s, c]: quota
    q_vars = {}
    for s in slot_ids:
        for c in class_ids:
            if c in allowed_slots[c]:
                q_vars[(s, c)] = model.addVar(name=f"q_{s}_{c}", vtype="I", lb=0, ub=max_total_quota, obj=quota_admin_cost)

    # t[s, b]: extra teams
    t_vars = {}
    for s in slot_ids:
        for b in block_ids:
            t_vars[(s, b)] = model.addVar(name=f"t_{s}_{b}", vtype="I", lb=0, ub=block_max_teams[b], obj=extra_team_cost)

    # a[w, s, c]: admit
    a_vars = {}
    for w in scen_ids:
        for s in slot_ids:
            for c in class_ids:
                if c in allowed_slots[c]:
                    d = demand.get((w, s, c), 0)
                    if d > 0:
                        a_vars[(w, s, c)] = model.addVar(name=f"a_{w}_{s}_{c}", vtype="I", lb=0, ub=d, obj=0)

    # v[w, s, b, c]: service
    v_vars = {}
    for w in scen_ids:
        for s in slot_ids:
            s_idx = slot_index[s]
            for c in class_ids:
                if s_idx > latest_service[c]:
                    continue
                for b in block_ids:
                    if (c, b) in elig:
                        v_vars[(w, s, b, c)] = model.addVar(name=f"v_{w}_{s}_{b}_{c}", vtype="I", lb=0, ub=max_total_quota, obj=0)

    # z: tail risk auxiliary
    z_var = model.addVar(name="z", vtype="C", lb=0, ub=1e6, obj=0)

    # Set objective: fixed cost + weighted scenario cost + tail risk
    # We'll build the objective expression
    obj_expr = 0.0

    # Fixed cost is already in variable objectives (quota_admin_cost * q + extra_team_cost * t)
    # Now add scenario costs

    # For each scenario, compute cost_w = handling + shortage + waiting
    # handling: sum over s,b,c of h_cb * v[w,s,b,c]
    # shortage: sum over s,c of pi_c * (D[w,s,c] - a[w,s,c])
    # waiting: sum over s,c of eta_c * Q[w,s,c] where Q is cumulative queue

    # We need to express waiting cost in terms of variables.
    # Q[w,s,c] = sum_{s'<=s} a[w,s',c] - sum_{s'<=s, b} v[w,s',b,c]
    # This is a linear expression.

    # Let's build cost_w as a linear expression for each scenario
    cost_exprs = {}
    for w in scen_ids:
        expr = 0.0
        # Handling cost
        for s in slot_ids:
            for c in class_ids:
                for b in block_ids:
                    if (w, s, b, c) in v_vars:
                        _, h = elig[(c, b)]
                        expr += h * v_vars[(w, s, b, c)]
        # Shortage cost
        for s in slot_ids:
            for c in class_ids:
                d = demand.get((w, s, c), 0)
                if d > 0 and (w, s, c) in a_vars:
                    expr += shortage_penalty[c] * (d - a_vars[(w, s, c)])
        # Waiting cost: sum over s of eta_c * Q[w,s,c]
        # Q[w,s,c] = cum_admit - cum_service
        # sum_s eta_c * Q[w,s,c] = sum_s eta_c * (sum_{s'<=s} a[w,s',c] - sum_{s'<=s,b} v[w,s',b,c])
        # = sum_{s'} a[w,s',c] * (sum_{s>=s'} eta_c) - sum_{s',b} v[w,s',b,c] * (sum_{s>=s'} eta_c)
        # Let suffix_eta[s',c] = sum_{s>=s'} eta_c
        for c in class_ids:
            eta = waiting_cost[c]
            # Compute suffix sum of eta over slots
            # For slot s', contribution to waiting is eta * (number of slots from s' to end)
            # Actually: sum_{s=s'}^{12} eta_c = eta_c * (12 - slot_index[s'] + 1)
            for s in slot_ids:
                s_idx = slot_index[s]
                n_slots_after = len(slot_ids) - s_idx  # number of slots from s to end inclusive
                if (w, s, c) in a_vars:
                    expr += eta * n_slots_after * a_vars[(w, s, c)]
                for b in block_ids:
                    if (w, s, b, c) in v_vars:
                        expr -= eta * n_slots_after * v_vars[(w, s, b, c)]
        cost_exprs[w] = expr

    # Add to objective: sum_w p_w * cost_w
    for w in scen_ids:
        obj_expr += scen_prob[w] * cost_exprs[w]

    # Tail risk: z >= cost_w - alpha for all w
    for w in scen_ids:
        model.addCons(z_var >= cost_exprs[w] - tail_risk_alpha, name=f"tail_{w}")

    # Set objective
    model.setObjective(obj_expr + tail_risk_weight * z_var, "minimize")

    # -----------------------------------------------------------------------
    # Constraints
    # -----------------------------------------------------------------------

    # 1. Quota window: q=0 if c not in allowed_slots[c] (already enforced by not creating var)

    # 2. Per-slot minimum quota
    for s in slot_ids:
        min_q = int(slot_data[s]["min_quota"])
        q_sum = quicksum(q_vars[(s, c)] for c in class_ids if (s, c) in q_vars)
        model.addCons(q_sum >= min_q, name=f"min_quota_{s}")

    # 3. Day total quota bounds
    total_q = quicksum(q_vars[(s, c)] for s in slot_ids for c in class_ids if (s, c) in q_vars)
    model.addCons(total_q >= min_total_quota, name="min_total_quota")
    model.addCons(total_q <= max_total_quota, name="max_total_quota")

    # 4. Quota ramp limit
    for i in range(1, len(slot_ids)):
        s_prev = slot_ids[i - 1]
        s_curr = slot_ids[i]
        q_prev = quicksum(q_vars[(s_prev, c)] for c in class_ids if (s_prev, c) in q_vars)
        q_curr = quicksum(q_vars[(s_curr, c)] for c in class_ids if (s_curr, c) in q_vars)
        model.addCons(q_curr - q_prev <= quota_ramp_limit, name=f"ramp_up_{s_curr}")
        model.addCons(q_prev - q_curr <= quota_ramp_limit, name=f"ramp_down_{s_curr}")

    # 5. Per-block team cap (already in ub)

    # 6. Terminal team cap
    for s in slot_ids:
        t_sum = quicksum(t_vars[(s, b)] for b in block_ids)
        model.addCons(t_sum <= max_extra_teams_per_slot, name=f"team_cap_{s}")

    # 7. Pool cap
    for pl in pool_limits:
        s = pl["slot_id"]
        pool_blocks = set(pl["blocks"].split("|"))
        cap = int(pl["max_extra_teams"])
        t_sum = quicksum(t_vars[(s, b)] for b in pool_blocks if (s, b) in t_vars)
        model.addCons(t_sum <= cap, name=f"pool_{pl['pool_id']}_{s}")

    # 8-9. Admit <= quota and admit <= demand (ub already set to demand)
    for w in scen_ids:
        for s in slot_ids:
            for c in class_ids:
                if (w, s, c) in a_vars:
                    if (s, c) in q_vars:
                        model.addCons(a_vars[(w, s, c)] <= q_vars[(s, c)], name=f"admit_le_quota_{w}_{s}_{c}")
                    else:
                        model.addCons(a_vars[(w, s, c)] == 0, name=f"admit_zero_{w}_{s}_{c}")

    # 10. Gate capacity
    for w in scen_ids:
        gm = scen_gate_mult[w]
        for s in slot_ids:
            gc = int(slot_data[s]["base_gate_capacity"]) * gm
            a_sum = quicksum(a_vars[(w, s, c)] for c in class_ids if (w, s, c) in a_vars)
            model.addCons(a_sum <= gc, name=f"gate_{w}_{s}")

    # 11. Reefer limit
    for w in scen_ids:
        for s in slot_ids:
            rl = int(slot_data[s]["reefer_inspection_limit"])
            reefer_classes = [c for c in class_ids if reefer_flag[c] == 1 and (w, s, c) in a_vars]
            if reefer_classes:
                a_sum = quicksum(a_vars[(w, s, c)] for c in reefer_classes)
                model.addCons(a_sum <= rl, name=f"reefer_{w}_{s}")

    # 12. Exposure cap
    for w in scen_ids:
        for s in slot_ids:
            ec = float(slot_data[s]["drayage_exposure_cap"])
            exp_sum = quicksum(exposure_units[c] * a_vars[(w, s, c)] for c in class_ids if (w, s, c) in a_vars)
            model.addCons(exp_sum <= ec, name=f"exposure_{w}_{s}")

    # 13. Channel cap
    for ml in mix_limits:
        s = ml["slot_id"]
        channel_classes = set(ml["classes"].split("|"))
        cap = int(ml["max_admissions"])
        for w in scen_ids:
            a_sum = quicksum(a_vars[(w, s, c)] for c in channel_classes if (w, s, c) in a_vars)
            model.addCons(a_sum <= cap, name=f"channel_{ml['rule_id']}_{w}_{s}")

    # 16. Cumulative service <= cumulative admit
    for w in scen_ids:
        for c in class_ids:
            for s in slot_ids:
                s_idx = slot_index[s]
                cum_a = quicksum(a_vars[(w, sp, c)] for sp in slot_ids[:s_idx + 1] if (w, sp, c) in a_vars)
                cum_v = quicksum(v_vars[(w, sp, b, c)] for sp in slot_ids[:s_idx + 1] for b in block_ids if (w, sp, b, c) in v_vars)
                model.addCons(cum_v <= cum_a, name=f"flow_{w}_{c}_{s}")

    # 17. Full service: total service = total admit
    for w in scen_ids:
        for c in class_ids:
            total_a = quicksum(a_vars[(w, s, c)] for s in slot_ids if (w, s, c) in a_vars)
            total_v = quicksum(v_vars[(w, s, b, c)] for s in slot_ids for b in block_ids if (w, s, b, c) in v_vars)
            model.addCons(total_v == total_a, name=f"full_service_{w}_{c}")

    # 18. Queue limit
    for w in scen_ids:
        for s in slot_ids:
            s_idx = slot_index[s]
            ql = int(slot_data[s]["queue_limit_trucks"])
            # Queue = sum_c (cum_admit_c - cum_service_c)
            # = sum_c cum_admit_c - sum_c cum_service_c
            cum_a_all = quicksum(a_vars[(w, sp, c)] for sp in slot_ids[:s_idx + 1] for c in class_ids if (w, sp, c) in a_vars)
            cum_v_all = quicksum(v_vars[(w, sp, b, c)] for sp in slot_ids[:s_idx + 1] for b in block_ids for c in class_ids if (w, sp, b, c) in v_vars)
            model.addCons(cum_a_all - cum_v_all <= ql, name=f"queue_{w}_{s}")

    # 19. Cutoff zero queue
    for w in scen_ids:
        for c in class_ids:
            if cutoff_zero[c] == 1:
                ls_idx = latest_service[c]
                for s in slot_ids:
                    s_idx = slot_index[s]
                    if s_idx >= ls_idx:
                        cum_a = quicksum(a_vars[(w, sp, c)] for sp in slot_ids[:s_idx + 1] if (w, sp, c) in a_vars)
                        cum_v = quicksum(v_vars[(w, sp, b, c)] for sp in slot_ids[:s_idx + 1] for b in block_ids if (w, sp, b, c) in v_vars)
                        model.addCons(cum_v == cum_a, name=f"cutoff_{w}_{c}_{s}")

    # 20. Service commitments
    for cm in commitments:
        w = cm["scenario_id"]
        c = cm["class_id"]
        by_s = cm["by_slot_id"]
        min_served = int(cm["min_served_trucks"])
        by_idx = slot_index[by_s]
        cum_v = quicksum(v_vars[(w, sp, b, c)] for sp in slot_ids[:by_idx + 1] for b in block_ids if (w, sp, b, c) in v_vars)
        model.addCons(cum_v >= min_served, name=f"commit_{w}_{c}_{by_s}")

    # 21. Block work capacity
    for w in scen_ids:
        for s in slot_ids:
            for b in block_ids:
                mult = block_cap.get((w, s, b), 1.0)
                base_w = block_base_work[b]
                cap_rhs = mult * base_w + team_work_unit_gain * t_vars[(s, b)]
                work_sum = quicksum(elig[(c, b)][0] * v_vars[(w, s, b, c)] for c in class_ids if (w, s, b, c) in v_vars)
                model.addCons(work_sum <= cap_rhs, name=f"block_cap_{w}_{s}_{b}")

    # -----------------------------------------------------------------------
    # Solve
    # -----------------------------------------------------------------------
    print("Solving model...")
    print(f"  Variables: {model.getNVars()}")
    print(f"  Constraints: {model.getNConss()}")
    print(f"  Time limit: {time_limit}s")

    model.optimize()

    status = model.getStatus()
    print(f"  Status: {status}")

    if status not in ("optimal", "bestsollimit", "timelimit"):
        print("  WARNING: No feasible solution found!")
        # Write empty solution
        with open(os.path.join(OUT_DIR, "solution.csv"), "w", newline="") as f:
            writer = csv.writer(f)
            writer.writerow(["row_type", "scenario_id", "slot_id", "class_id", "block_id", "value"])
        return

    obj_val = model.getObjval()
    print(f"  Objective: {obj_val:.6f}")

    # -----------------------------------------------------------------------
    # Extract solution
    # -----------------------------------------------------------------------
    rows = []

    # Quota rows
    for s in slot_ids:
        for c in class_ids:
            if (s, c) in q_vars:
                val = round(model.getVal(q_vars[(s, c)]))
                if val > 0:
                    rows.append(["quota", "", s, c, "", str(val)])

    # Team rows
    for s in slot_ids:
        for b in block_ids:
            val = round(model.getVal(t_vars[(s, b)]))
            if val > 0:
                rows.append(["team", "", s, "", b, str(val)])

    # Admit rows
    for w in scen_ids:
        for s in slot_ids:
            for c in class_ids:
                if (w, s, c) in a_vars:
                    val = round(model.getVal(a_vars[(w, s, c)]))
                    if val > 0:
                        rows.append(["admit", w, s, c, "", str(val)])

    # Service rows
    for w in scen_ids:
        for s in slot_ids:
            for b in block_ids:
                for c in class_ids:
                    if (w, s, b, c) in v_vars:
                        val = round(model.getVal(v_vars[(w, s, b, c)]))
                        if val > 0:
                            rows.append(["service", w, s, c, b, str(val)])

    # Write solution
    os.makedirs(OUT_DIR, exist_ok=True)
    sol_path = os.path.join(OUT_DIR, "solution.csv")
    with open(sol_path, "w", newline="") as f:
        writer = csv.writer(f)
        writer.writerow(["row_type", "scenario_id", "slot_id", "class_id", "block_id", "value"])
        for row in rows:
            writer.writerow(row)

    print(f"  Solution written to {sol_path} with {len(rows)} rows")

    # Validation
    print("\nValidation checks:")
    valid = True
    for row in rows:
        rt = row[0]
        val = int(row[5])
        if val < 0:
            print(f"  ERROR: Negative value in row {row}")
            valid = False
        if rt == "quota":
            if row[1] != "" or row[4] != "":
                print(f"  ERROR: Quota row has non-blank scenario/block: {row}")
                valid = False
        elif rt == "team":
            if row[1] != "" or row[3] != "":
                print(f"  ERROR: Team row has non-blank scenario/class: {row}")
                valid = False
        elif rt == "admit":
            if row[4] != "":
                print(f"  ERROR: Admit row has non-blank block: {row}")
                valid = False
        elif rt == "service":
            if row[1] == "" or row[2] == "" or row[3] == "" or row[4] == "":
                print(f"  ERROR: Service row has blank fields: {row}")
                valid = False
        else:
            print(f"  ERROR: Unknown row type: {row}")
            valid = False

    if valid:
        print("  All validation checks passed.")
    else:
        print("  Some validation checks FAILED.")


if __name__ == "__main__":
    solve()
